import{f as e,ag as p,o as r,s as a}from"./chunks/framework.D85dHE_g.js";const d=JSON.parse('{"title":"一切都要支付两次【转】","description":"","frontmatter":{},"headers":[],"relativePath":"关于生活/other/一切都要支付两次.md","filePath":"关于生活/other/一切都要支付两次.md","lastUpdated":1736483115000}'),o={name:"关于生活/other/一切都要支付两次.md"};function s(n,t,i,l,c,_){return p(),r("div",null,t[0]||(t[0]=[a('<h1 id="一切都要支付两次【转】" tabindex="-1">一切都要支付两次【转】 <a class="header-anchor" href="#一切都要支付两次【转】" aria-label="Permalink to &quot;一切都要支付两次【转】&quot;">​</a></h1><p>有一句古语“<a href="https://baike.baidu.com/item/%E9%BB%84%E7%94%9F%E5%80%9F%E4%B9%A6%E8%AF%B4/11002602" target="_blank" rel="noreferrer">书非借不能读也</a>”，大家可能都听过。</p><p>它的意思是，很多人买了书却不读，觉得不着急，拥有书就相当于已经开始学了，后面就慢慢来吧，反而是借来的书有急迫感会抓紧读完。</p><p><img src="https://cdn.beekka.com/blogimg/asset/202501/bg2025010101.webp" alt=""></p><p>这种事情很多。网址保存成书签，就扔在那里了，再也不去看它了。</p><p>我最近看到一篇<a href="https://www.raptitude.com/2022/01/everything-must-be-paid-for-twice/" target="_blank" rel="noreferrer">老外的文章</a>，他给这种现象起了一个全新的名字，让人觉得很贴切。老外的概念化能力真是强。</p><p>他提出，人们买书却不读，是因为没有意识到<strong>每样东西都需要两次支付</strong>。</p><p><img src="https://cdn.beekka.com/blogimg/asset/202501/bg2025010102.webp" alt=""></p><p>第一次是货币支付，你付出货币，得到自己想要的东西，比如一本书，一个 App，一辆自行车，一颗卷心菜等等。</p><p>但是，你还必须支付第二次，才能真正消费这个东西。这次你付出的是你的时间和努力，来获得它的收益。</p><p>第二次支付可能比第一次支付贵得多。假设一本书的第一次支付是20元，第二次支付可能就是10小时的阅读时间。只有支付第二次，你才算真正消费了这本书。如果没有第二次支付，第一次支付就意义不大了，跟把钱扔进垃圾箱差不多。</p><p>生活中，到处都是两次支付的例子。购买 App 后，你必须学习如何使用，并且经常使用，才能得到它的价值。购买自行车后，你必须忍受痛苦的初学者阶段，然后才能上街骑行。购买蔬菜后，必须切碎、蒸熟并咀嚼，然后才能为你提供营养。</p><p><strong>我们经常犯的一个错误，就是只完成了第一次支付，没有第二次支付</strong>，比如未使用的会员资格，未读的书籍，未玩的游戏，未编织的毛线。由于没有第二次支付，所以你并没有真正使用，第一次支付的钱实际上扔进了垃圾桶。</p><p>这种行为方式的深层次原因，就是<strong>现代社会太强调消费</strong>，过于看重第一次支付的经济价值，而忽视第二次支付的实际结果。人们受到消费主义的影响，以为支付了商品价格，就完成了一次消费。</p><p>合理的消费方式应该是，<strong>只有当你确定会有第二次支付，才进行第一次支付</strong>。这样就可以避免许许多多的浪费。</p><p>新的一年，大家购买商品时，可以先问问自己，你会不会第二次支付，即会不会为它付出时间和努力？只有确信自己会，再掏钱购买它。</p><p>有一种商品，天然支持先进行第二次支付，再进行第一次支付，那就是软件。</p><p>软件不同于实体商品，边际成本接近零，又是长期消费，完全可以先让用户免费用（试用版或者试用期），等他用习惯了，再向他收费。</p><p>很多软件就是这样做的，这大概就是为什么，软件的不理性消费行为，要比实体商品少得多的原因。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>本文转自阮一峰老师的【科技爱好者周刊】第 333 期：<a href="https://github.com/ruanyf/weekly/blob/master/docs/issue-333.md" target="_blank" rel="noreferrer">一切都要支付两次</a></p><p>本人特别喜欢阮一峰老师的周刊，基本每期都不会落下，这里转载完全出于个人喜爱（如有不当请联系：luofatso@gamil.com）。</p></div>',20)]))}const g=e(o,[["render",s]]);export{d as __pageData,g as default};
